from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import Optional
import json
import os
from pathlib import Path

app = FastAPI()

# Directory to store queue data
DATA_DIR = Path("/workdir/data")
DATA_DIR.mkdir(parents=True, exist_ok=True)

# Queue data storage - each queue is a list of messages
# We'll use a dictionary mapping queue_name -> list of messages
queues = {}

class QueueCreate(BaseModel):
    name: str

class MessageCreate(BaseModel):
    content: str

def get_queue_path(name: str) -> Path:
    """Get the file path for a queue's data."""
    return DATA_DIR / f"{name}.json"

def load_queue(name: str) -> list:
    """Load queue messages from file."""
    path = get_queue_path(name)
    if path.exists():
        with open(path, 'r') as f:
            return json.load(f)
    return []

def save_queue(name: str, messages: list):
    """Save queue messages to file."""
    path = get_queue_path(name)
    with open(path, 'w') as f:
        json.dump(messages, f)

def queue_exists(name: str) -> bool:
    """Check if a queue exists."""
    return name in queues or get_queue_path(name).exists()

@app.post("/queues")
def create_queue(queue: QueueCreate):
    """Create a new queue."""
    name = queue.name
    # Initialize queue if not exists
    if not queue_exists(name):
        queues[name] = []
        save_queue(name, [])
    return {"message": f"Queue '{name}' created successfully"}

@app.post("/queues/{queue_name}/messages")
def send_message(queue_name: str, message: MessageCreate):
    """Send a message to a queue."""
    # Create queue if it doesn't exist
    if not queue_exists(queue_name):
        raise HTTPException(status_code=404, detail=f"Queue '{queue_name}' not found")

    # Load current messages
    messages = load_queue(queue_name)
    # Append new message
    messages.append(message.content)
    # Save back
    save_queue(queue_name, messages)
    return {"message": f"Message sent to queue '{queue_name}'", "content": message.content}

@app.get("/queues/{queue_name}/messages")
def receive_message(queue_name: str):
    """Receive/consume one message from a queue (FIFO)."""
    # Check if queue exists
    if not queue_exists(queue_name):
        raise HTTPException(status_code=404, detail=f"Queue '{queue_name}' not found")

    # Load messages
    messages = load_queue(queue_name)

    # If empty, return 204
    if len(messages) == 0:
        return None  # FastAPI will return 204 for None response

    # Get first message (FIFO)
    msg = messages.pop(0)
    # Save back
    save_queue(queue_name, messages)
    return {"content": msg}

@app.get("/status")
def get_status():
    """Return basic service status."""
    return {"status": "ok", "queues_count": len(queues)}

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
